// @ts-check

import { getRequire } from '../../../utils/Runtime.js'
import { UtilsConst } from '../../../utils/UtilsConst.js'

const requireDynamic = getRequire(import.meta.url)
const fs = requireDynamic('fs')
const path = requireDynamic('path')

class ActivationHelper {
    /**
     * Returns the license key from hypertube.lic, falling back to the key
     * configured through RuntimeBridge or a configuration file.
     * @returns {string}
     */
    static getLicenseKey() {
        try {
            return ActivationHelper.getLicenseKeyFromFile()
        } catch {
            return UtilsConst.getLicenseKey()
        }
    }

    /**
     * Reads the license key from hypertube.lic in the SDK working directory.
     * Both the XML license format and the JSON format used by some SDK versions
     * are supported.
     * @returns {string}
     */
    static getLicenseKeyFromFile() {
        const licensePath = path.join(UtilsConst.getWorkingDirectory(), 'hypertube.lic')
        if (!fs.existsSync(licensePath)) {
            throw new Error('License file not found.')
        }

        const contents = fs.readFileSync(licensePath, 'utf8')
        const licenseKey =
            ActivationHelper.#getLicenseKeyFromJson(contents) ||
            ActivationHelper.#getLicenseKeyFromXml(contents)

        if (!licenseKey) {
            throw new Error('License key not found in hypertube.lic.')
        }
        return licenseKey
    }

    /**
     * @param {string} contents
     * @returns {string}
     */
    static #getLicenseKeyFromJson(contents) {
        try {
            const document = JSON.parse(contents)
            const activateResult = document?.ActivateResult
            const innerValue = typeof activateResult === 'string' ? activateResult : activateResult?.Value
            if (typeof innerValue !== 'string') {
                return ''
            }

            const innerDocument = JSON.parse(innerValue)
            return typeof innerDocument?.licenceKey === 'string' ? innerDocument.licenceKey.trim() : ''
        } catch {
            return ''
        }
    }

    /**
     * @param {string} contents
     * @returns {string}
     */
    static #getLicenseKeyFromXml(contents) {
        const activateResult = contents.match(
            /<(?:[\w.-]+:)?ActivateResult\b[^>]*>([\s\S]*?)<\/(?:[\w.-]+:)?ActivateResult>/i
        )?.[1]
        if (!activateResult) {
            return ''
        }

        const innerXml = ActivationHelper.#decodeXml(
            activateResult.replace(/^<!\[CDATA\[([\s\S]*?)\]\]>$/i, '$1')
        )
        const licenseKey = innerXml.match(
            /<(?:[\w.-]+:)?licenceKey\b[^>]*>([\s\S]*?)<\/(?:[\w.-]+:)?licenceKey>/i
        )?.[1]
        return licenseKey ? ActivationHelper.#decodeXml(licenseKey).trim() : ''
    }

    /**
     * @param {string} value
     * @returns {string}
     */
    static #decodeXml(value) {
        return value
            .replace(/&lt;/g, '<')
            .replace(/&gt;/g, '>')
            .replace(/&quot;/g, '"')
            .replace(/&apos;/g, "'")
            .replace(/&amp;/g, '&')
    }
}

export { ActivationHelper }
